function minAddToMakeValid(s) {
  const stack = [];
  let unmatchedClose = 0;
  for (const ch of s) {
    if (ch === '(') {
      stack.push(ch);
    } else if (stack.length > 0) {
      stack.pop();
    } else {
      unmatchedClose++;
    }
  }
  return unmatchedClose + stack.length;
}

